command:
c:dpkg -s auditd -> r:install ok installed || c:rpm -q audit -> r:^audit-;
f:/etc/audit/auditd.conf -> r:^log_file\s+/var/log/audit/audit.log;
f:/etc/audit/auditd.conf -> r:^log_format\s+raw;
f:/etc/audit/auditd.conf -> r:^flush\s+(INCREMENTAL|INCREMENTAL_ASYNC);
f:/etc/audit/auditd.conf -> r:^max_log_file_action\s+keep_logs;
f:/etc/audit/auditd.conf -> r:^space_left\s+75;
f:/etc/audit/auditd.conf -> r:^action_mail_acct\s+root;
f:/etc/audit/auditd.conf -> r:^space_left_action\s+SYSLOG;
f:/etc/audit/auditd.conf -> r:^admin_space_left\s+50;
f:/etc/audit/auditd.conf -> r:^admin_space_left_action\s+SUSPEND;
f:/etc/audit/auditd.conf -> r:^disk_full_action\s+SUSPEND;
f:/etc/audit/auditd.conf -> r:^disk_error_action\s+SUSPEND;

not c:test -w /etc/login.defs;
f:/etc/login.defs -> r:^SYS_UID_MIN\s+201;
f:/etc/login.defs -> r:^SYS_UID_MAX\s+999;
f:/etc/login.defs -> r:^SYS_GID_MIN\s+201;
f:/etc/login.defs -> r:^SYS_GID_MAX\s+999;

f:/etc/passwd;
c:stat -c '%U %G %a' /etc/passwd -> r:^root root;
c:stat -c %a /etc/passwd -> n:(\d+) compare <= 644;
not c:test -x /etc/passwd;

f:/etc/modprobe.d/dev-sec.conf -> r:install cramfs /bin/true;
f:/etc/modprobe.d/dev-sec.conf -> r:install freevxfs /bin/true;
f:/etc/modprobe.d/dev-sec.conf -> r:install jffs2 /bin/true;
f:/etc/modprobe.d/dev-sec.conf -> r:install hfs /bin/true;
f:/etc/modprobe.d/dev-sec.conf -> r:install hfsplus /bin/true;
f:/etc/modprobe.d/dev-sec.conf -> r:install squashfs /bin/true;
f:/etc/modprobe.d/dev-sec.conf -> r:install udf /bin/true;
f:/etc/modprobe.d/dev-sec.conf -> r:install vfat /bin/true;

f:/etc/shadow;
c:stat -c %U /etc/shadow -> =:root;
not c:test -x /etc/shadow;
c:stat -c %a /etc/shadow -> n:(\d+) compare <= 640;

f:/etc/login.defs;
c:stat -c %U /etc/login.defs -> =:root;
c:stat -c %G /etc/login.defs -> =:root;
f:/etc/login.defs -> r:^LOGIN_RETRIES\s+5;
f:/etc/login.defs -> r:^LOGIN_TIMEOUT\s+60;
f:/etc/login.defs -> r:^UID_MIN\s+1000;
f:/etc/login.defs -> r:^GID_MIN\s+1000;
